// Closing: only at MAIN, and only after a completed authority lookup in the
// last hour confirmed that this same work order at this same site was GRANTED
// by a HUMAN approver. The lookup must have a ::response event, so a failed or
// denied lookup (recorded as ::error) cannot satisfy this condition.
@id("close_workorder_with_human_approval")
permit (principal, action == Drupe::Action::"close_workorder", resource)
when { context.input.site_id == "MAIN" }
when temporal {
  formerly within 1h Drupe::Action::"authority_get_approval"::response{
    eventResource: resource,
    input.wonum: context.input.wonum,
    input.site_id: context.input.site_id,
    output.decision: Drupe::authority_get_approval_Output_decision::"GRANTED",
    output.approver_kind: Drupe::authority_get_approval_Output_approver_kind::"HUMAN"
  }
};

// The agent must never approve work orders itself (belt and braces; there is
// also no permit for this action).
@id("never_approve_workorder")
forbid (principal, action == Drupe::Action::"approve_workorder", resource);
